
package com.unblu.webapi.model.v4;

import com.fasterxml.jackson.annotation.JsonCreator;
import com.fasterxml.jackson.annotation.JsonValue;

/**
 * How the content of a conversation message was produced. The value is set when the message is created and doesn&#39;t change afterward.
 */
public enum EMessageContentOrigin {

	/**
	 * AI_GENERATED: The content was generated by an AI system.
	 */
	AI_GENERATED("AI_GENERATED"),

	/**
	 * AI_MODIFIED: The content was written by a person with the help of an AI system, for example an agent who edited and sent a suggestion drafted by AI.
	 */
	AI_MODIFIED("AI_MODIFIED");

	private String value;

	EMessageContentOrigin(String value) {
		this.value = value;
	}

	@JsonValue
	public String getValue() {
		return value;
	}

	@Override
	public String toString() {
		return String.valueOf(value);
	}

	@JsonCreator
	public static EMessageContentOrigin fromValue(String value) {
		for (EMessageContentOrigin b : EMessageContentOrigin.values()) {
			if (b.value.equals(value)) {
				return b;
			}
		}
		throw new IllegalArgumentException("Unexpected value '" + value + "'");
	}
}
